"""Self-contained dfnWorks stage driver.

The Windows MCP process writes this source next to each job's ``spec.json`` and
executes it with the WSL venv interpreter. It deliberately imports nothing from
``fracman_mcp`` so it can run on the Linux side unchanged.
"""

DRIVER_SOURCE = r'''#!/usr/bin/env python3
"""dfnWorks stage driver generated by wmw-fracman-mcp. Do not edit by hand.

Usage: python -u driver.py <job_dir>

Stages
------
generate : build the DFN, export statistics and fracture geometry
mesh     : generate + LaGriT conforming mesh, export mesh statistics
graph    : generate + connectivity graph, backbone and graph metrics
"""
from __future__ import annotations

import csv
import json
import math
import os
import sys
import time
import traceback
from datetime import datetime, timezone
from pathlib import Path


def now_iso():
    return datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")


def write_json(path, payload):
    path = Path(path)
    tmp = path.with_suffix(path.suffix + ".tmp")
    with open(tmp, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2, ensure_ascii=False, default=str)
    os.replace(tmp, path)


def stats(values):
    data = sorted(float(value) for value in values if math.isfinite(float(value)))
    if not data:
        return {"min": None, "max": None, "mean": None, "median": None}
    count = len(data)
    mean = sum(data) / count
    if count % 2:
        median = data[count // 2]
    else:
        median = 0.5 * (data[count // 2 - 1] + data[count // 2])
    return {"min": data[0], "max": data[-1], "mean": mean, "median": median}


def newell(poly):
    sx = sy = sz = 0.0
    count = len(poly)
    for index in range(count):
        x1, y1, z1 = poly[index]
        x2, y2, z2 = poly[(index + 1) % count]
        sx += y1 * z2 - z1 * y2
        sy += z1 * x2 - x1 * z2
        sz += x1 * y2 - y1 * x2
    return sx, sy, sz


def mean_pole(items):
    tx = ty = tz = 0.0
    for item in items:
        nx, ny, nz = item["normal"]
        if nz < 0:
            nx, ny, nz = -nx, -ny, -nz
        length = math.sqrt(nx * nx + ny * ny + nz * nz)
        if length <= 1e-15:
            continue
        tx += nx / length
        ty += ny / length
        tz += nz / length
    length = math.sqrt(tx * tx + ty * ty + tz * tz)
    if length <= 1e-15:
        return None
    x, y, z = tx / length, ty / length, tz / length
    return {
        "trend": math.degrees(math.atan2(x, y)) % 360.0,
        "plunge": math.degrees(math.asin(max(-1.0, min(1.0, z)))),
    }


def collect_fractures(dfn):
    # pydfnworks stores one family id per accepted fracture in ``dfn.families``
    # (column 3 of radii.dat); older builds expose the same data as ``family``.
    families = None
    for name in ("families", "family"):
        value = getattr(dfn, name, None)
        if value is None:
            continue
        try:
            families = [int(item) for item in value]
        except TypeError:
            continue
        if families:
            break
    families = families or []
    items = []
    bbox = None
    for key, array in (getattr(dfn, "polygons", None) or {}).items():
        try:
            index = int(str(key).rsplit("-", 1)[-1])
        except ValueError:
            continue
        poly = [(float(row[0]), float(row[1]), float(row[2])) for row in array]
        if len(poly) < 3:
            continue
        sx, sy, sz = newell(poly)
        magnitude = math.sqrt(sx * sx + sy * sy + sz * sz)
        area = 0.5 * magnitude
        if magnitude > 1e-15:
            normal = (sx / magnitude, sy / magnitude, sz / magnitude)
            if normal[2] < 0:
                normal = (-normal[0], -normal[1], -normal[2])
        else:
            normal = (0.0, 0.0, 0.0)
        cx = sum(v[0] for v in poly) / len(poly)
        cy = sum(v[1] for v in poly) / len(poly)
        cz = sum(v[2] for v in poly) / len(poly)
        radius = max(math.dist(v, (cx, cy, cz)) for v in poly)
        family = families[index - 1] if 0 < index <= len(families) else None
        try:
            family = int(family)
        except (TypeError, ValueError):
            family = None
        for x, y, z in poly:
            if bbox is None:
                bbox = {"min": [x, y, z], "max": [x, y, z]}
            else:
                bbox["min"] = [min(bbox["min"][0], x), min(bbox["min"][1], y),
                               min(bbox["min"][2], z)]
                bbox["max"] = [max(bbox["max"][0], x), max(bbox["max"][1], y),
                               max(bbox["max"][2], z)]
        items.append({
            "id": index,
            "family": family,
            "vertices": [list(v) for v in poly],
            "center": [cx, cy, cz],
            "normal": list(normal),
            "area": area,
            "radius": radius,
        })
    items.sort(key=lambda item: item["id"])
    return items, bbox


def read_declared_families(run_dir):
    path = Path(run_dir) / "dfnGen_output" / "families.dat"
    if not path.is_file():
        return []
    records = []
    current = {}
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            stripped = line.strip()
            if not stripped:
                if current:
                    records.append(current)
                    current = {}
                continue
            if ": " in stripped:
                key, value = stripped.split(": ", 1)
                current[key.strip()] = value.strip()
    if current:
        records.append(current)
    return records


def read_connections(run_dir):
    path = Path(run_dir) / "dfnGen_output" / "fracture_info.dat"
    if not path.is_file():
        return None
    values = []
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        header = next(handle, "")
        if "num_connections" not in header:
            return None
        for line in handle:
            parts = line.split()
            if not parts:
                continue
            try:
                values.append(int(float(parts[0])))
            except ValueError:
                continue
    return values


def intersection_stats(dfn):
    try:
        data = dfn.intersection_list
    except Exception:
        return None
    if data is None:
        return None
    rows = getattr(data, "tolist", lambda: data)()
    if not rows:
        return {"count": 0, "total_length": 0.0, "length": stats([])}
    if not isinstance(rows[0], list):
        rows = [rows]
    lengths = []
    for row in rows:
        try:
            f1, f2, length = float(row[0]), float(row[1]), float(row[5])
        except (TypeError, ValueError, IndexError):
            continue
        if f1 > 0 and f2 > 0 and math.isfinite(length):
            lengths.append(length)
    return {
        "count": len(lengths),
        "total_length": sum(lengths),
        "length": stats(lengths),
    }


def summarise(dfn, items, bbox, spec):
    areas = [item["area"] for item in items]
    radii = [item["radius"] for item in items]
    family_counts = {}
    family_area = {}
    for item in items:
        key = "unknown" if item["family"] is None else str(item["family"])
        family_counts[key] = family_counts.get(key, 0) + 1
        family_area[key] = family_area.get(key, 0.0) + item["area"]
    domain = [float(value) for value in spec["domain"]]
    volume = domain[0] * domain[1] * domain[2]
    connections = read_connections(spec["_run_dir"]) or []
    intersections = intersection_stats(dfn)
    return {
        "fracture_count": len(items),
        "family_counts": family_counts,
        "family_total_area": family_area,
        "declared_families": read_declared_families(spec["_run_dir"]),
        "area": stats(areas),
        "total_area": sum(areas),
        "radius": stats(radii),
        "bbox": bbox,
        "domain": domain,
        "domain_volume": volume,
        "p32": (sum(areas) / volume) if volume > 0 else None,
        "mean_pole": mean_pole(items),
        "intersections": intersections,
        "connection_degree": stats(connections) if connections else None,
        "num_frac_object": int(getattr(dfn, "num_frac", 0) or 0),
    }


def mesh_statistics(run_dir, dfn):
    run_dir = Path(run_dir)
    nodes = triangles = None
    inp = run_dir / "full_mesh.inp"
    if inp.is_file():
        with open(inp, "r", encoding="utf-8", errors="replace") as handle:
            header = handle.readline().split()
        if len(header) >= 2:
            try:
                nodes, triangles = int(header[0]), int(header[1])
            except ValueError:
                pass
    materials = None
    material_file = run_dir / "materialid.dat"
    if material_file.is_file():
        # LaGriT dump: a short preamble, then ``imt1, integer`` followed by one
        # material id per node.  Distinct ids = matrix + fracture materials.
        values = set()
        started = False
        with open(material_file, "r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                if not started:
                    started = "imt1" in line
                    continue
                for token in line.split():
                    try:
                        values.add(int(token))
                    except ValueError:
                        continue
        materials = len(values) or None
    files = {}
    for name in ("full_mesh.inp", "full_mesh.uge", "materialid.dat",
                 "reduced_mesh.inp", "reduced_mesh.uge"):
        path = run_dir / name
        if path.is_file():
            files[name] = path.stat().st_size
    return {
        "nodes": nodes,
        "triangles": triangles,
        "materials": materials,
        "files": files,
        "fracture_count_after_mesh": int(getattr(dfn, "num_frac", 0) or 0),
    }


def graph_statistics(dfn, job_dir, spec):
    import networkx as nx

    gspec = spec["graph"]
    graph = dfn.create_graph(
        gspec["graph_type"], gspec["inflow"], gspec["outflow"]
    )
    result = {
        "graph_type": gspec["graph_type"],
        "inflow": gspec["inflow"],
        "outflow": gspec["outflow"],
        "nodes": graph.number_of_nodes(),
        "edges": graph.number_of_edges(),
        "fracture_nodes": max(0, graph.number_of_nodes() - 2),
        "source_target_present": bool(
            graph.has_node("s") and graph.has_node("t")
        ),
    }
    try:
        result["density"] = nx.density(graph)
    except Exception:
        pass
    try:
        result["components"] = nx.number_connected_components(graph)
        result["source_target_connected"] = bool(nx.has_path(graph, "s", "t"))
    except Exception as exc:
        result["components"] = None
        result["source_target_connected"] = False
        result["connectivity_error"] = f"{type(exc).__name__}: {exc}"

    if result.get("source_target_connected"):
        try:
            path = nx.shortest_path(graph, "s", "t")
            result["shortest_path_edges"] = len(path) - 1
            result["shortest_path_fractures"] = max(0, len(path) - 2)
        except Exception:
            pass
        try:
            backbone = dfn.k_shortest_paths_backbone(graph, gspec["k"])
            result["backbone"] = {
                "k": gspec["k"],
                "nodes": backbone.number_of_nodes(),
                "edges": backbone.number_of_edges(),
            }
            dfn.dump_json_graph(backbone, str(Path(job_dir) / "backbone"))
            try:
                dfn.dump_fractures(
                    backbone, str(Path(job_dir) / "backbone_fractures.txt")
                )
            except Exception as exc:
                result["backbone"]["fracture_list_error"] = (
                    f"{type(exc).__name__}: {exc}"
                )
        except Exception as exc:
            result["backbone"] = {
                "k": gspec["k"],
                "error": f"{type(exc).__name__}: {exc}",
            }

    dfn.dump_json_graph(graph, str(Path(job_dir) / "graph"))
    return result


def export_fractures(job_dir, items, domain):
    payload = {
        "domain": domain,
        "fracture_count": len(items),
        "fractures": items,
    }
    write_json(Path(job_dir) / "fractures.json", payload)
    with open(Path(job_dir) / "fractures.csv", "w", newline="",
              encoding="utf-8") as handle:
        writer = csv.writer(handle)
        writer.writerow([
            "id", "family", "area", "radius", "cx", "cy", "cz",
            "nx", "ny", "nz", "vertex_count",
        ])
        for item in items:
            writer.writerow([
                item["id"], item["family"], item["area"], item["radius"],
                item["center"][0], item["center"][1], item["center"][2],
                item["normal"][0], item["normal"][1], item["normal"][2],
                len(item["vertices"]),
            ])


def collect_artifacts(job_dir, run_dir):
    artifacts = []
    for path in (
        Path(job_dir) / "dfn_stats.json",
        Path(job_dir) / "fractures.json",
        Path(job_dir) / "fractures.csv",
        Path(job_dir) / "mesh_stats.json",
        Path(job_dir) / "graph.json",
        Path(job_dir) / "graph_metrics.json",
        Path(job_dir) / "backbone.json",
        Path(run_dir) / "full_mesh.inp",
        Path(run_dir) / "full_mesh.uge",
        Path(run_dir) / "materialid.dat",
        Path(run_dir) / "dfnGen_output" / "polygons.dat",
        Path(run_dir) / "dfnGen_output" / "families.dat",
        Path(run_dir) / "dfnGen_output" / "connectivity.dat",
    ):
        if path.is_file():
            artifacts.append(
                {"path": str(path), "size_bytes": path.stat().st_size}
            )
    return artifacts


def main():
    if len(sys.argv) < 2:
        print("usage: driver.py <job_dir>", file=sys.stderr)
        return 2
    job_dir = Path(sys.argv[1]).resolve()
    spec = json.loads((job_dir / "spec.json").read_text(encoding="utf-8"))
    run_dir = job_dir / "run"
    spec["_run_dir"] = str(run_dir)
    stage = spec.get("stage", "generate")
    result = {
        "ok": False,
        "stage": stage,
        "job_dir": str(job_dir),
        "started_at": now_iso(),
    }
    code = 0
    os.chdir(job_dir)
    try:
        import pydfnworks
        from pydfnworks import DFNWORKS

        result["pydfnworks_version"] = getattr(pydfnworks, "__version__", "unknown")
        print(f"[dfnworks] stage={stage} start", flush=True)

        started = time.time()
        dfn = DFNWORKS(str(run_dir), ncpu=int(spec["ncpu"]))
        params = dfn.params
        params["domainSize"]["value"] = spec["domain"]
        params["h"]["value"] = spec["h"]
        params["orientationOption"]["value"] = spec["orientation_option"]
        params["stopCondition"]["value"] = spec["stop_condition"]
        params["nPoly"]["value"] = spec["n_poly"]
        params["seed"]["value"] = spec["seed"]
        params["boundaryFaces"]["value"] = spec["boundary_faces"]
        for family in spec["families"]:
            dfn.add_fracture_family(**family)

        dfn.make_working_directory(delete=True)
        dfn.check_input()
        dfn.create_network()
        result["timing"] = {"generate_s": round(time.time() - started, 3)}
        print(
            f"[dfnworks] generated {getattr(dfn, 'num_frac', '?')} fractures",
            flush=True,
        )

        items, bbox = collect_fractures(dfn)
        result["dfn"] = summarise(dfn, items, bbox, spec)
        write_json(job_dir / "dfn_stats.json", result["dfn"])
        export_fractures(job_dir, items, spec["domain"])

        if spec.get("output_report"):
            started = time.time()
            dfn.output_report(verbose=False)
            result["timing"]["report_s"] = round(time.time() - started, 3)

        if stage == "mesh":
            print("[dfnworks] meshing with LaGriT", flush=True)
            started = time.time()
            dfn.mesh_network(**spec["mesh"], quiet=True)
            result["timing"]["mesh_s"] = round(time.time() - started, 3)
            result["mesh"] = mesh_statistics(run_dir, dfn)
            write_json(job_dir / "mesh_stats.json", result["mesh"])
            print(
                f"[dfnworks] mesh nodes={result['mesh']['nodes']} "
                f"triangles={result['mesh']['triangles']}",
                flush=True,
            )

        if stage == "graph":
            print("[dfnworks] building connectivity graph", flush=True)
            started = time.time()
            result["graph"] = graph_statistics(dfn, job_dir, spec)
            result["timing"]["graph_s"] = round(time.time() - started, 3)
            write_json(job_dir / "graph_metrics.json", result["graph"])
            print(
                f"[dfnworks] graph nodes={result['graph']['nodes']} "
                f"edges={result['graph']['edges']} "
                f"connected={result['graph']['source_target_connected']}",
                flush=True,
            )

        result["ok"] = True
        result["message"] = "completed"
        print("[dfnworks] completed", flush=True)
    except BaseException as exc:
        code = 1
        result["error"] = f"{type(exc).__name__}: {exc}"
        result["traceback"] = traceback.format_exc()[-8000:]
        print(result["traceback"], file=sys.stderr, flush=True)
    finally:
        result["finished_at"] = now_iso()
        try:
            result["artifacts"] = collect_artifacts(job_dir, run_dir)
        except Exception:
            result["artifacts"] = []
        write_json(job_dir / "result.json", result)
    return code


if __name__ == "__main__":
    sys.exit(main())
'''
